/* BfK-1 · LF6 · P9 — Weine aus nah und fern & Bier Zusammenfassung */
(function(){
  window.toggleVi = function(){
    var wrap = document.querySelector('.weine-skript-wrap') || document.querySelector('.bier-skript-wrap') || document.body;
    wrap.classList.toggle('hide-vi');
    var b = document.getElementById('viToggle');
    var hidden = wrap.classList.contains('hide-vi');
    if(b) b.textContent = hidden ? 'VI: TẮT' : 'VI: BẬT';
  };
  window.toggleAns = function(id){
    var e = document.getElementById(id);
    if(e) e.style.display = (e.style.display==='none'||!e.style.display) ? 'block' : 'none';
  };
  window.toggleFlipMode = function(){
    var sec = document.getElementById('rebsorten');
    if(!sec) return;
    var on = sec.classList.toggle('quiz');
    var fm = document.getElementById('flipMode');
    if(fm){
      fm.textContent = on ? 'Tắt chế độ lật thẻ' : 'Bật chế độ lật thẻ';
      fm.setAttribute('aria-pressed', on);
    }
    if(!on){
      document.querySelectorAll('.card.open').forEach(function(c){ c.classList.remove('open'); });
    }
  };
})();

